mapper.select:



        AND (university_name like concat('%', #{universityName}, '%') or aliases ilike concat('%', #{universityName}, '%'))


        AND province = #{province}


        AND tier = #{tier}


        AND campus_type = #{campusType}


        AND status = #{status}


order by case tier when 'c9' then 1 when '985' then 2 when '211' then 3 when 'double_first_class' then 4 else 5 end,
         campus_type, cn_university_id
